hooks.command:
# WHY: globals.css is the single source of colour. Two bypasses keep recurring
# and both break light mode:
#   - Tailwind palette literals (red-400 is 2.4:1 on the light ground)
#   - text-amber used as TEXT (amber is a FILL; 1.83:1 on light, fails AA)
# Scans only STAGED .ts/.tsx, skipping surfaces that legitimately hardcode
# colour: OG/satori image routes and HTML email templates cannot read CSS vars.
# text-amber-lift/-sink ARE tokens, so the lookahead excludes a trailing hyphen.
$j = [Console]::In.ReadToEnd() | ConvertFrom-Json
if ($j.tool_input.command -notlike '*git commit*') { exit 0 }
$root = (git rev-parse --show-toplevel 2>$null)
if (-not $root) { exit 0 }
$bad = @()
foreach ($f in @(git diff --cached --name-only --diff-filter=ACM)) {
  if ($f -notmatch '[.](ts|tsx)$') { continue }
  if ($f -match 'node_modules|__tests__|/email/|/og/|opengraph|constants/wrapped') { continue }
  $fp = Join-Path $root $f
  if (-not (Test-Path $fp)) { continue }
  $pat = @('(text|bg|border|ring|from|to|via|decoration)-(red|zinc|neutral|gray|slate|stone)-[0-9]', 'text-amber(?![-a-zA-Z0-9])')
  $hits = Select-String -Path $fp -Pattern $pat -AllMatches -ErrorAction SilentlyContinue
  foreach ($h in $hits) { $bad += ('  ' + $f + ':' + $h.LineNumber + '  ' + $h.Line.Trim()) }
}
if ($bad.Count -gt 0) {
  $NL = [char]10
  $msg = 'Colour tokens bypassed in staged files. globals.css is the single source of colour.' + $NL + $NL +
         ($bad -join $NL) + $NL + $NL +
         'Fix: Tailwind palette colours -> text-destructive.' + $NL +
         'Amber as TEXT -> text-ember (amber is a FILL; 1.83:1 on light, fails WCAG AA).'
  @{hookSpecificOutput=@{hookEventName='PreToolUse';permissionDecision='deny';permissionDecisionReason=$msg}} | ConvertTo-Json -Compress
}

# WHY: push is the last cheap place to catch a broken build. Runs the two fast
# gates (typecheck + lint) and BLOCKS on failure. Tests are deliberately NOT run
# here: the suite is ~11 minutes, too slow to sit in front of every push, so it
# is enforced at PR time instead. Resolves tsc/eslint from apps/web first and
# then the repo root, since this is an npm-workspaces monorepo.
$j = [Console]::In.ReadToEnd() | ConvertFrom-Json
if ($j.tool_input.command -notlike '*git push*') { exit 0 }
$root = (git rev-parse --show-toplevel 2>$null)
if (-not $root) { exit 0 }
$w = Join-Path $root 'apps/web'
if (-not (Test-Path $w)) { exit 0 }
$tsc = @((Join-Path $w 'node_modules/typescript/bin/tsc'), (Join-Path $root 'node_modules/typescript/bin/tsc')) | Where-Object { Test-Path $_ } | Select-Object -First 1
$esl = @((Join-Path $w 'node_modules/eslint/bin/eslint.js'), (Join-Path $root 'node_modules/eslint/bin/eslint.js')) | Where-Object { Test-Path $_ } | Select-Object -First 1
$NL = [char]10
$problems = @()
Push-Location $w
if ($tsc) { $r = node $tsc --noEmit 2>&1 | Out-String; if ($LASTEXITCODE -ne 0) { $problems += ('TYPECHECK FAILED:' + $NL + $r) } }
if ($esl) { $r = node $esl src 2>&1 | Out-String; if ($LASTEXITCODE -ne 0) { $problems += ('LINT FAILED:' + $NL + $r) } }
Pop-Location
if ($problems.Count -gt 0) {
  $msg = ($problems -join ($NL + $NL)) + $NL + $NL + 'Fix before pushing. Rule 12: do not report success if anything was skipped.'
  @{hookSpecificOutput=@{hookEventName='PreToolUse';permissionDecision='deny';permissionDecisionReason=$msg}} | ConvertTo-Json -Compress
}
